-- Only reorder a complete catalog that still has the untouched 0100 order.
-- The new ranks are explicit design families, not IDs or name sorting.
SET @muse_original_order = (
  SELECT COUNT(*) = 79 AND COUNT(DISTINCT template.sort_order - item.seed_order * 10) = 1
  FROM resume_templates AS template
  JOIN JSON_TABLE(@muse_curation, '$[*]' COLUMNS (
    template_key VARCHAR(64) PATH '$.key', seed_order INT PATH '$.seed_order'
  )) AS item ON item.template_key = template.`key`
  WHERE template.style_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].definition'))
);
SET @muse_sort_base = COALESCE((
  SELECT MAX(template.sort_order)
  FROM resume_templates AS template
  LEFT JOIN JSON_TABLE(@muse_curation, '$[*]' COLUMNS (
    template_key VARCHAR(64) PATH '$.key'
  )) AS item ON item.template_key = template.`key`
  WHERE item.template_key IS NULL
), 0);

-- Downlisting preserves IDs, definitions, samples, foreign keys and snapshots.
UPDATE resume_templates AS template
JOIN JSON_TABLE(@muse_curation, '$[*]' COLUMNS (
  template_key VARCHAR(64) PATH '$.key', seed_order INT PATH '$.seed_order', curated_rank INT PATH '$.rank'
)) AS item ON item.template_key = template.`key`
SET template.is_active = 0
WHERE item.curated_rank = 0 AND template.is_active = 1
  AND template.style_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].definition'));

UPDATE resume_templates AS template
JOIN JSON_TABLE(@muse_curation, '$[*]' COLUMNS (
  template_key VARCHAR(64) PATH '$.key', seed_order INT PATH '$.seed_order', curated_rank INT PATH '$.rank'
)) AS item ON item.template_key = template.`key`
SET template.sort_order = LEAST(@muse_sort_base + item.curated_rank * 10, 1000000)
WHERE @muse_original_order = 1 AND item.curated_rank > 0 AND template.is_active = 1
  AND template.style_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].definition'));

-- Fill only unreviewed empty labels. Do not reactivate a manually disabled seed.
UPDATE resume_templates AS template
JOIN JSON_TABLE(@muse_curation, '$[*]' COLUMNS (
  template_key VARCHAR(64) PATH '$.key', seed_order INT PATH '$.seed_order', curated_rank INT PATH '$.rank'
)) AS item ON item.template_key = template.`key`
SET template.style_categories_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].style_categories')),
    template.use_cases_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].use_cases')),
    template.style_review_status = 'classified'
WHERE item.curated_rank > 0 AND template.is_active = 1
  AND template.style_review_status = 'pending'
  AND COALESCE(JSON_LENGTH(template.style_categories_json), 0) = 0
  AND COALESCE(JSON_LENGTH(template.use_cases_json), 0) = 0
  AND template.style_json = JSON_EXTRACT(@muse_curation, CONCAT('$[', item.seed_order - 1, '].definition'));
